package com.crh.logon.webservices.clients.beans.pricingcall;

import java.io.Serializable;
import java.util.List;

/**
 * @author AdNovum Informatik AG
 * 
 * Data Transfer Object from business tier to the webservice client 
 * tier. This object will be created and filled in the business tier, and 
 * converted/read in the webservices-client tier into the data model for SAP
 * as generated by AXIS.
 * 
 * Represents: ZFSD_PRICE_SIMULATION / {@code ZTSD_PS_PARTNERS} 
 */
public class PricingCallDTOPartners implements Serializable {

	private static final long serialVersionUID = -2805599221981299113L;

	/**
	 * WS field to SAP: ZFSD_PRICE_SIMULATION / ZTSD_PS_PARTNERS / item
	 */
	private List<PricingCallDTOPartner> items;

	public List<PricingCallDTOPartner> getItems() {
		return items;
	}

	public void setItems(List<PricingCallDTOPartner> items) {
		this.items = items;
	}

	@Override
	public String toString() {
		return "PricingCallDTOPartners [items=" + items + "]";
	}
	
}